<script setup>
import {Link,useForm,router}from'@inertiajs/vue3';import AdminLayout from '../../../Layouts/AdminLayout.vue';
const props=defineProps({word:Object});const editing=!!props.word;const detail=props.word?.detail||{};const form=useForm({headword:props.word?.headword||'',ipa:props.word?.ipa||'',partOfSpeech:props.word?.part_of_speech||'',meaning:props.word?.meaning||'',frequencyLabel:props.word?.frequency_label||'',audioAsset:props.word?.audio_asset||'',slug:props.word?.slug||'',detailType:detail.type||'richtext',detailHtml:detail.html||'',detailUrl:detail.url||'',detailTitle:detail.title||'',detailSummary:detail.summary||''});
function save(){form.submit(editing?'put':'post',editing?`/admin/words/${props.word.id}`:'/admin/words');}function publish(){router.post(`/admin/words/${props.word.id}/${props.word.status==='published'?'unpublish':'publish'}`)}
</script>
<template><AdminLayout :title="editing?'编辑单词':'新建单词'" section="内容管理 / 单词管理" :description="editing?`单词 ID #${word.id} · 编辑资料和详解`:'添加新单词与对应详解。'"><template #actions><Link class="btn secondary" href="/admin/words">← 返回列表</Link></template><div class="split-panel"><div class="form-stack"><section class="card"><div class="card-header"><div><h2>单词资料</h2><p>基本释义、发音和资料标识</p></div></div><div class="card-body"><form class="form-stack" @submit.prevent="save"><div class="form-grid"><div class="form-field"><label>单词 *</label><input v-model="form.headword" class="input" required></div><div class="form-field"><label>音标</label><input v-model="form.ipa" class="input"></div><div class="form-field"><label>词性</label><input v-model="form.partOfSpeech" class="input" placeholder="n. / v. / adj."></div><div class="form-field"><label>简明释义 *</label><input v-model="form.meaning" class="input" required></div><div class="form-field"><label>频率标签</label><input v-model="form.frequencyLabel" class="input"></div><div class="form-field"><label>发音资源路径</label><input v-model="form.audioAsset" class="input"></div><div class="form-field"><label>内容标识 slug</label><input v-model="form.slug" class="input"></div><div class="form-field"><label>详解形式</label><select v-model="form.detailType" class="select"><option value="richtext">富文本详解</option><option value="officialAccount">公众号文章链接</option></select></div></div><div v-if="form.detailType==='richtext'" class="form-field"><label>单词详解正文</label><div class="toolbar"><button type="button" @click="command('bold')"><b>粗体</b></button><button type="button" @click="command('italic')"><i>斜体</i></button><button type="button" @click="command('insertUnorderedList')">列表</button><button type="button" @click="command('formatBlock','h3')">小标题</button></div><div ref="editor" class="rich-editor" contenteditable="true" data-placeholder="填写词义辨析、用法和例句…" @input="form.detailHtml=$event.target.innerHTML" v-html="form.detailHtml"></div></div><div v-else class="form-grid"><div class="form-field wide"><label>公众号文章链接</label><input v-model="form.detailUrl" class="input" type="url"></div><div class="form-field"><label>文章标题</label><input v-model="form.detailTitle" class="input"></div><div class="form-field"><label>摘要</label><input v-model="form.detailSummary" class="input"></div></div><div class="section-actions"><button class="btn" :disabled="form.processing">保存单词与详解</button></div></form></div></section></div><aside class="form-stack"><section class="card"><div class="card-header"><h2>发布状态</h2></div><div class="card-body"><template v-if="editing"><p><span class="status" :class="word.status">{{word.status==='published'?'已发布':'草稿'}}</span></p><p class="helper">发布后，该单词可被精读文章和每日学习引用。</p><button class="btn" :class="word.status==='published'?'danger':''" @click="publish">{{word.status==='published'?'下架单词':'发布单词'}}</button></template><p v-else class="helper">保存后默认为草稿。</p></div></section></aside></div></AdminLayout></template>
<script>export default {methods:{command(cmd,value){document.execCommand(cmd,false,value||null)}}}</script>
